#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

int main() {
    struct Node *head = NULL;
    struct Node *tail = NULL;
    int index;

    // Create the first node with value 0
    head = (struct Node *)malloc(sizeof(struct Node));
    head->value = 0;
    head->next = NULL;
    tail = head;

    // Create three additional nodes with values 1, 2, 3
    for (index = 1; index <= 3; index++) {
        struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));
        newNode->value = index;
        newNode->next = NULL;
        tail->next = newNode;
        tail = newNode;
    }

    // Traverse the list and print each value
    struct Node *current = head;
    index = 0;
    while (current != NULL) {
        printf("Value at index %d is %d\n", index, current->value);
        current = current->next;
        index++;
    }

    // Free all allocated memory
    current = head;
    while (current != NULL) {
        struct Node *temp = current;
        current = current->next;
        free(temp);
    }

    return 0;
}

